SELECT * FROM (SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'RI:' || i.instruction_id event_id, m.material_id case_id, 'Rolling Instruction Released' activity, i.released_at timestamp FROM rolling_instruction i JOIN as_rolled_material m ON i.instruction_id=m.instruction_id UNION ALL SELECT 'YD:' || tracking_id event_id, material_id case_id, 'Yard Instruction Received' activity, yard_instruction_received_at timestamp FROM furnace_charge_tracking UNION ALL SELECT 'RH:' || material_id event_id, material_id case_id, 'Reheating Started' activity, furnace_charged_at timestamp FROM as_rolled_material WHERE furnace_charged_at IS NOT NULL UNION ALL SELECT 'CS:' || material_id event_id, material_id case_id, 'Crop Shear Passed' activity, crop_shear_passed_at timestamp FROM as_rolled_material WHERE crop_shear_passed_at IS NOT NULL UNION ALL SELECT 'CI:' || instruction_id event_id, material_id case_id, 'Cutting Instruction Released' activity, released_at timestamp FROM cutting_finishing_instruction UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Rolling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='RL' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Cooling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='CO' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Leveling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='LE' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Split Cutting Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='SC' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Heat Treatment Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='HT' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Inspection Failed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='IF' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Inspection Passed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='IP' UNION ALL SELECT 'DIM:' || p.plate_material_id event_id, m.material_id case_id, 'Dimensional Inspection Completed' activity, p.dimension_inspected_at timestamp FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no WHERE p.dimension_inspected_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM slab_material_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM planned_rolling_instruction_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM rolling_instruction_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM furnace_charge_tracking_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM cutting_finishing_instruction_activity UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM plate_material_activity) e JOIN (SELECT 'YD:' || tracking_id event_id, tracking_id case_id FROM furnace_charge_tracking UNION ALL SELECT event_id,case_id FROM lifecycle_case_link WHERE case_table='furnace_charge_tracking') m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id) WHERE activity IN ('Furnace Charge Assigned','Furnace Charge Confirmed','Furnace Discharge Confirmed') ORDER BY case_id,timestamp,event_id;
